<script setup>
import { computed } from 'vue'
import { getProject, projects } from '../data/projects.js'
const props = defineProps({slug:{type:String,required:true}})
const project = computed(()=>getProject(props.slug))
const next = computed(()=>{const index=projects.findIndex(p=>p.slug===props.slug); return projects[(index+1)%projects.length]})
</script>
<template><div v-if="project" class="wrap case-study"><RouterLink to="/work" class="text-link">← All work</RouterLink><div class="eyebrow case-eyebrow">CASE STUDY {{ project.number }} / {{ project.category }}</div><h1 class="case-title">{{ project.name }}<span class="dot">.</span></h1><p class="case-deck">{{ project.summary }}</p><div class="case-cover"><img v-if="project.image" :src="project.image" :alt="'Screenshot of '+project.name"/><div v-else class="cover-placeholder"><span>VISUAL DOCUMENTATION</span><strong>{{ project.name }}</strong><small>Actual application screenshots to be added</small></div></div><div class="case-meta"><div><span>YEAR</span><strong>{{ project.year }}</strong></div><div><span>MY ROLE</span><strong>{{ project.role }}</strong></div><div><span>TECHNOLOGIES / FOCUS</span><strong>{{ project.stack.join(' · ') }}</strong></div></div><div class="article"><section><span class="eyebrow">01 / CONTEXT</span><h2>The problem</h2><p>{{ project.problem }}</p></section><section><span class="eyebrow">02 / PROCESS</span><h2>Design approach</h2><p>{{ project.approach }}</p></section><section><span class="eyebrow">03 / ENGINEERING</span><h2>Implementation</h2><p>{{ project.implementation }}</p></section><section><span class="eyebrow">04 / REFLECTION</span><h2>Lessons & next steps</h2><p>{{ project.learnings }}</p></section><p v-if="project.confidentiality" class="notice">{{ project.confidentiality }}</p><div v-if="project.github || project.live" class="case-links"><a v-if="project.github" :href="project.github" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a v-if="project.live" :href="project.live" target="_blank" rel="noopener noreferrer">Live application ↗</a></div></div><RouterLink class="next-case" :to="'/work/'+next.slug"><span>NEXT PROJECT ↗</span><strong>{{ next.name }}</strong></RouterLink></div><div v-else class="wrap page-top"><h1>Project not found.</h1><RouterLink to="/work" class="text-link">Return to work →</RouterLink></div></template>
